package com.jnapanam.sportszone.content.repository;import com.jnapanam.sportszone.content.model.*;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface AnnouncementRepository extends JpaRepository<Announcement,UUID>{@Query("select a from Announcement a where a.status=:status and a.publishFrom<=:now and (a.publishUntil is null or a.publishUntil>=:now) order by a.priority desc,a.publishFrom desc")List<Announcement>active(@Param("status")ContentStatus status,@Param("now")Instant now);List<Announcement>findAllByOrderByCreatedAtDesc();}
